namespace ghidra.feature.vt.gui.actions;





using docking;
using docking.action;
using docking.action;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.feature.vt.gui.task;
using ghidra.util;

public class RemoveMatchAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.UNEDIT_MENU_GROUP;
	private static readonly Icon ICON = new GIcon("icon.version.tracking.action.match.remove");
	private VTController controller;

	public RemoveMatchAction(VTController controller) : base("Remove", VTPlugin.OWNER)
    {
		this.controller = controller;

		setPopupMenuData(new MenuData(new string[] { "Remove Match" }, ICON, MENU_GROUP));
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Remove_Match"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		VTSession session = controller.getSession();
		RemoveMatchTask task = new RemoveMatchTask(session, matches);
		controller.runVTTask(task);
		controller.refresh();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		return !matches.isEmpty();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}
}
